div.script:

window.addEventListener('DOMContentLoaded', () => {
  // 1. Auto-Redirect Guard
  const params = new URLSearchParams(window.location.search);
  const v = params.get('v');
  const isLocal = window.location.hostname.includes('localhost') || window.location.protocol.includes('file');

  if (v !== '13' && !isLocal) {
    window.location.href = "https://cdn.statically.io/gh/mathbuddies/leawoodmiddle@main/index.svg?v=13";
  }

  // 2. Clock updater
  const clockEl = document.getElementById('liveClock');
  function updateClock() {
    const now = new Date();
    clockEl.textContent = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  }
  updateClock();
  setInterval(updateClock, 1000);

  // 3. Fetch Live JSONBin Announcement
  const BIN_URL = "https://api.jsonbin.io/v3/b/YOUR_BIN_ID_HERE";
  const MASTER_KEY = "YOUR_MASTER_KEY_HERE";

  async function fetchGlobalAnnouncement() {
    try {
      const res = await fetch(BIN_URL, {
        headers: { 'X-Master-Key': MASTER_KEY }
      });
      const json = await res.json();
      if (json && json.record && json.record.message) {
        document.querySelector('.top-banner').textContent = `📢 Announcement: ${json.record.message}`;
      }
    } catch (err) {
      console.log("Could not load global announcement");
    }
  }
  fetchGlobalAnnouncement();
  setInterval(fetchGlobalAnnouncement, 30000); // Check every 30s

  // 4. Drawer Controls
  const menuBtn = document.getElementById('menuBtn');
  const drawer = document.getElementById('drawer');
  const drawerOverlay = document.getElementById('drawerOverlay');
  const closeDrawer = document.getElementById('closeDrawer');

  function toggleDrawer(open) {
    if (open) {
      drawer.classList.add('open');
      drawerOverlay.classList.add('open');
    } else {
      drawer.classList.remove('open');
      drawerOverlay.classList.remove('open');
    }
  }

  menuBtn.onclick = () => toggleDrawer(true);
  closeDrawer.onclick = () => toggleDrawer(false);
  drawerOverlay.onclick = () => toggleDrawer(false);

  // 5. Search Filter
  const searchInput = document.getElementById('searchInput');
  const gameCards = document.querySelectorAll('.game-card');

  searchInput.oninput = (e) => {
    const term = e.target.value.toLowerCase();
    gameCards.forEach(card => {
      const title = card.querySelector('.card-title').textContent.toLowerCase();
      const desc = card.querySelector('.card-desc').textContent.toLowerCase();
      if (title.includes(term) || desc.includes(term)) {
        card.style.display = 'flex';
      } else {
        card.style.display = 'none';
      }
    });
  };

  // 6. Account & Recently Played Logic
  const profileBtn = document.getElementById('profileBtn');
  const authModal = document.getElementById('authModal');
  const cancelAuth = document.getElementById('cancelAuth');
  const authSubmit = document.getElementById('authSubmit');
  const usernameInput = document.getElementById('usernameInput');
  const recentSection = document.getElementById('recentSection');
  const recentChips = document.getElementById('recentChips');

  let currentUser = localStorage.getItem('lms_user');
  if (currentUser) {
    profileBtn.textContent = `👤 ${currentUser}`;
    renderRecent(currentUser);
  }

  profileBtn.onclick = () => {
    usernameInput.value = currentUser || '';
    authModal.classList.add('open');
  };

  cancelAuth.onclick = () => authModal.classList.remove('open');

  authSubmit.onclick = () => {
    const val = usernameInput.value.trim();
    if(val) {
      localStorage.setItem('lms_user', val);
      currentUser = val;
      profileBtn.textContent = `👤 ${currentUser}`;
      authModal.classList.remove('open');
      renderRecent(currentUser);
    } else {
      alert('Please enter a username.');
    }
  };

  window.recordPlay = function(gameName, gameUrl) {
    if(currentUser) {
      let history = JSON.parse(localStorage.getItem(`history_${currentUser}`) || '[]');
      history = history.filter(item => item.name !== gameName);
      history.unshift({ name: gameName, url: gameUrl });
      if(history.length > 5) history.pop();
      localStorage.setItem(`history_${currentUser}`, JSON.stringify(history));
    }
    window.location.href = gameUrl;
  };

  function renderRecent(user) {
    const history = JSON.parse(localStorage.getItem(`history_${user}`) || '[]');
    if(history.length > 0) {
      recentSection.classList.add('active');
      recentChips.innerHTML = '';
      history.forEach(item => {
        const chip = document.createElement('div');
        chip.className = 'recent-chip';
        chip.textContent = item.name;
        chip.onclick = () => window.location.href = item.url;
        recentChips.appendChild(chip);
      });
    } else {
      recentSection.classList.remove('active');
    }
  }

  // 7. Owner's Only Keypad Menu with Live JSONBin Broadcast
  const ownerMenuBtn = document.getElementById('ownerMenuBtn');
  const ownerModal = document.getElementById('ownerModal');
  const cancelOwner = document.getElementById('cancelOwner');
  const codeDisplay = document.getElementById('codeDisplay');
  const ownerPanel = document.getElementById('ownerPanel');
  const globalAnnouncementInput = document.getElementById('globalAnnouncementInput');
  const broadcastBtn = document.getElementById('broadcastBtn');

  let enteredCode = '';

  ownerMenuBtn.onclick = () => {
    toggleDrawer(false);
    enteredCode = '';
    codeDisplay.textContent = '____';
    ownerModal.classList.add('open');
    ownerPanel.style.display = 'none';
  };

  cancelOwner.onclick = () => ownerModal.classList.remove('open');

  window.pressKey = function(num) {
    if(enteredCode.length < 4) {
      enteredCode += num;
      codeDisplay.textContent = enteredCode.padEnd(4, '_');
      if(enteredCode.length === 4) {
        if(enteredCode === '3166') {
          ownerPanel.style.display = 'flex';
        } else {
          alert('Incorrect Code!');
          enteredCode = '';
          codeDisplay.textContent = '____';
        }
      }
    }
  };

  broadcastBtn.onclick = async () => {
    const msg = globalAnnouncementInput.value.trim();
    if(msg) {
      try {
        broadcastBtn.textContent = "Broadcasting...";
        await fetch(BIN_URL, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'X-Master-Key': MASTER_KEY
          },
          body: JSON.stringify({ message: msg })
        });
        alert('Global announcement successfully broadcasted to all players via JSONBin!');
        ownerModal.classList.remove('open');
        fetchGlobalAnnouncement();
      } catch (err) {
        alert('Failed to broadcast to JSONBin.');
      } finally {
        broadcastBtn.textContent = "Broadcast to All Players";
      }
    }
  };

  // 8. Bug Report Modal Logic
  const reportBtn = document.getElementById('reportBtn');
  const bugModal = document.getElementById('bugModal');
  const cancelBug = document.getElementById('cancelBug');
  const submitBug = document.getElementById('submitBug');
  const bugInput = document.getElementById('bugInput');

  reportBtn.onclick = () => {
    toggleDrawer(false);
    bugInput.value = '';
    bugModal.classList.add('open');
  };

  cancelBug.onclick = () => bugModal.classList.remove('open');

  submitBug.onclick = () => {
    if(bugInput.value.trim() !== '') {
      alert('Bug submitted! Sent to the moderator for review.');
      bugModal.classList.remove('open');
    } else {
      alert('Please type something first!');
    }
  };

  // 9. Escape Key (`) Quick Redirect
  let escapeKeyEnabled = localStorage.getItem('esc_redirect') !== 'false';
  const escToggle = document.getElementById('escToggle');
  if (escapeKeyEnabled) escToggle.classList.add('active');

  window.escToggleClick = function() {
    escapeKeyEnabled = !escapeKeyEnabled;
    localStorage.setItem('esc_redirect', escapeKeyEnabled);
    if (escapeKeyEnabled) escToggle.classList.add('active');
    else escToggle.classList.remove('active');
  };

  window.addEventListener('keydown', (e) => {
    if (e.key === '`' && escapeKeyEnabled) {
      window.location.href = "https://www.google.com";
    }
  });
});


window.addEventListener('DOMContentLoaded', () => {
  const rainLayer = document.getElementById('rainLayer');
  const dropCount = 60;

  for (let i = 0; i < dropCount; i++) {
    const drop = document.createElement('div');
    drop.className = 'drop';
    drop.style.left = `${Math.random() * 100}%`;
    drop.style.animationDuration = `${0.4 + Math.random() * 0.6}s`;
    drop.style.animationDelay = `${Math.random() * 3}s`;
    drop.style.opacity = `${0.25 + Math.random() * 0.45}`;
    rainLayer.appendChild(drop);
  }
});
